CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS doctor (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), external_system varchar(32) NOT NULL, external_user_id varchar(128) NOT NULL, employee_no varchar(64), display_name varchar(128) NOT NULL, department_id varchar(128), department_name varchar(128), role varchar(32) NOT NULL DEFAULT 'DOCTOR', status varchar(32) NOT NULL DEFAULT 'ACTIVE', last_login_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(external_system, external_user_id));
CREATE TABLE IF NOT EXISTS login_session (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), doctor_id uuid NOT NULL REFERENCES doctor(id), login_type varchar(32) NOT NULL, access_token_hash varchar(256) NOT NULL, expires_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(), client_info jsonb NOT NULL DEFAULT '{}'::jsonb, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS patient (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_system varchar(32) NOT NULL, source_patient_id varchar(128) NOT NULL, patient_no varchar(64), name varchar(128) NOT NULL, gender varchar(16), birth_date date, phone_masked varchar(64), phone_ciphertext text, id_no_hash varchar(128), department_id varchar(128), department_name varchar(128), source_updated_at timestamptz, status varchar(32) NOT NULL DEFAULT 'ACTIVE', raw_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_system, source_patient_id));
CREATE TABLE IF NOT EXISTS visit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visit_no varchar(64) NOT NULL UNIQUE, patient_id uuid NOT NULL REFERENCES patient(id), doctor_id uuid NOT NULL REFERENCES doctor(id), department_id varchar(128), department_name varchar(128), visit_date date NOT NULL DEFAULT current_date, status varchar(32) NOT NULL DEFAULT 'WAITING', chief_complaint text, patient_name_snapshot varchar(128), patient_gender_snapshot varchar(16), patient_age_snapshot int, started_at timestamptz, completed_at timestamptz, cancelled_at timestamptz, archive_reason varchar(256), current_record_id uuid, version int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_doctor_active_visit ON visit(doctor_id) WHERE status = 'ACTIVE';
CREATE TABLE IF NOT EXISTS recording (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visit_id uuid NOT NULL REFERENCES visit(id), recording_no varchar(64) NOT NULL, source_type varchar(32) NOT NULL, object_key varchar(512), file_name varchar(256), mime_type varchar(128), size_bytes bigint, duration_ms bigint, sha256 varchar(128), status varchar(32) NOT NULL DEFAULT 'UPLOADED', asr_route varchar(32), error_code varchar(64), error_message varchar(512), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(visit_id, recording_no));
CREATE TABLE IF NOT EXISTS recording_session (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visit_id uuid NOT NULL REFERENCES visit(id), recording_id uuid NOT NULL REFERENCES recording(id), stream_epoch bigint NOT NULL DEFAULT 1, recording_fencing_token varchar(128) NOT NULL, status varchar(32) NOT NULL DEFAULT 'OPEN', last_sequence bigint NOT NULL DEFAULT -1, last_event_id varchar(128), started_at timestamptz NOT NULL DEFAULT now(), stopped_at timestamptz, stop_operation_id varchar(128) UNIQUE, reconnect_count int NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS asr_utterance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visit_id uuid NOT NULL REFERENCES visit(id), recording_id uuid NOT NULL REFERENCES recording(id), session_id uuid NOT NULL REFERENCES recording_session(id), utterance_id varchar(128) NOT NULL, revision int NOT NULL, result_type varchar(32) NOT NULL, text text NOT NULL, role varchar(32) NOT NULL DEFAULT 'UNKNOWN', anonymous_speaker_epoch int NOT NULL DEFAULT 1, start_ms bigint, end_ms bigint, is_current boolean NOT NULL DEFAULT false, source_event_id varchar(128), ignored_reason varchar(128), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(utterance_id, revision, result_type));
CREATE UNIQUE INDEX IF NOT EXISTS uq_current_canonical_utterance ON asr_utterance(utterance_id) WHERE result_type = 'CANONICAL' AND is_current = true;
CREATE TABLE IF NOT EXISTS dialogue_snapshot (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visit_id uuid NOT NULL UNIQUE REFERENCES visit(id), recording_id uuid NOT NULL REFERENCES recording(id), session_id uuid NOT NULL REFERENCES recording_session(id), snapshot_version int NOT NULL DEFAULT 1, snapshot_hash varchar(128) NOT NULL UNIQUE, authority_status varchar(64) NOT NULL, turns_json jsonb NOT NULL, created_by uuid REFERENCES doctor(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS medical_record (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visit_id uuid NOT NULL UNIQUE REFERENCES visit(id), current_version int NOT NULL DEFAULT 0, status varchar(32) NOT NULL DEFAULT 'DRAFT', confirmed_version int, confirmed_at timestamptz, confirmed_by uuid REFERENCES doctor(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS medical_record_version (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES medical_record(id), version_no int NOT NULL, source_snapshot_id uuid NOT NULL REFERENCES dialogue_snapshot(id), source_snapshot_hash varchar(128) NOT NULL, content_json jsonb NOT NULL DEFAULT '{}'::jsonb, edited_content_json jsonb, generation_status varchar(32) NOT NULL DEFAULT 'PENDING', generated_by varchar(128), created_by uuid REFERENCES doctor(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(record_id, version_no));
CREATE TABLE IF NOT EXISTS medical_record_confirmation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES medical_record(id), version_id uuid NOT NULL REFERENCES medical_record_version(id), doctor_id uuid NOT NULL REFERENCES doctor(id), declaration boolean NOT NULL, confirmed_at timestamptz NOT NULL DEFAULT now(), client_ip varchar(64));
CREATE TABLE IF NOT EXISTS ai_job (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_type varchar(32) NOT NULL, visit_id uuid NOT NULL REFERENCES visit(id), source_snapshot_hash varchar(128), idempotency_key varchar(256) NOT NULL UNIQUE, status varchar(32) NOT NULL DEFAULT 'PENDING', attempt_count int NOT NULL DEFAULT 0, provider_route varchar(32), result_ref uuid, last_error varchar(1024), started_at timestamptz, finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
